tool_input.command:
python3 - <<'EOF'
p='src/pickList.ts'
s=open(p).read()
s=s.replace('''export function buildPickList(_ordersText: string, _stock: StockLot[]): PickList {
  throw new Error("Not implemented");
}''','''export function buildPickList(_ordersText: string, _stock: StockLot[]): PickList {
  return { picks: [], shortages: [] };
}''')
open(p,'w').write(s)
EOF
bun test 2>&1 | tail -3

cat >> src/pickList.test.ts <<'EOF'

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({ bin, sku, qty, expires });

test("one item covered by one lot gives one pick", () => {
  const result = buildPickList("ORDER 1001\n  OLIVE-500 x3", [lot("A-01-1", "OLIVE-500", 10)]);
  expect(result).toEqual({
    picks: [{ bin: "A-01-1", sku: "OLIVE-500", qty: 3, orderId: "1001" }],
    shortages: [],
  });
});
EOF
bun test 2>&1 | grep -E "pass|fail"

cat >> src/pickList.test.ts <<'EOF'

test("item without any stock is reported as shortage", () => {
  const result = buildPickList("ORDER 1001\n  OLIVE-500 x3", []);
  expect(result).toEqual({
    picks: [],
    shortages: [{ orderId: "1001", sku: "OLIVE-500", missing: 3 }],
  });
});
EOF
bun test 2>&1 | grep -E "^\(fail\)| pass| fail"
